import{_ as n,c as r,o as t,ah as a}from"./chunks/framework.dGCgOE9J.js";const i="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_geopackage_download.jpg",b=JSON.parse('{"title":"24. Daten importieren und exportieren","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/24-daten-import-und-export.md","filePath":"manual/teil-b-betrieb-admin-qgis/24-daten-import-und-export.md"}'),o={name:"manual/teil-b-betrieb-admin-qgis/24-daten-import-und-export.md"};function l(s,e,d,h,u,m){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="_24-daten-importieren-und-exportieren" tabindex="-1">24. Daten importieren und exportieren <a class="header-anchor" href="#_24-daten-importieren-und-exportieren" aria-label="Permalink to &quot;24. Daten importieren und exportieren&quot;">​</a></h1><p>Qonnectra hat keinen allgemeinen Import. Daten kommen auf drei Wegen in eine Installation: Rohre über den Excel-Import der Rohrverwaltung, Geometrien – Trassen, Netzknoten, Adressen, Gebiete – über QGIS, und alles Übrige über die Weboberfläche. Dieses Kapitel beschreibt, was die Administration für diese Wege vorbereitet, und in welcher Reihenfolge ein neues Projekt befüllt wird. Welche Exporte die Weboberfläche bietet, steht in Abschnitt <a href="./../teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.html#_3-8-exportformate-im-uberblick">Exportformate im Überblick</a>.</p><h2 id="_24-1-excel-import-der-rohre-vorlage-und-pflichtspalten" tabindex="-1">24.1 Excel-Import der Rohre: Vorlage und Pflichtspalten <a class="header-anchor" href="#_24-1-excel-import-der-rohre-vorlage-und-pflichtspalten" aria-label="Permalink to &quot;24.1 Excel-Import der Rohre: Vorlage und Pflichtspalten&quot;">​</a></h2><p>Den Ablauf des Imports, die Vorlage und die Fehlermeldungen beschreibt Abschnitt <a href="./../teil-a-anwenderhandbuch/10-rohrverwaltung.html#_10-5-excel-import-vorlage-ablauf-fehlermeldungen">Excel-Import: Vorlage, Ablauf, Fehlermeldungen</a>. Aus Sicht der Administration zählt, was vorher vorhanden sein muss.</p><p>Jeder Wert in den Spalten „Typ“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Projekt“ und „Kennzeichen“ muss als Stammdatum existieren, bevor die Datei importiert wird. Der Import vergleicht buchstabengenau, einschließlich Groß- und Kleinschreibung und Leerzeichen; „Geplant“ findet den Status „geplant“ nicht. Legen Sie fehlende Werte vorher an, siehe Kapitel <a href="./21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Firmennamen müssen eindeutig sein. Gibt es zwei Firmen mit demselben Namen, meldet der Import für jede Zeile, die diesen Namen als „Eigentümer“, „Baufirma“ oder „Hersteller“ nennt, „An unexpected error occurred“ – und übernimmt damit die ganze Datei nicht. Prüfen Sie die Liste der Firmen vor einem großen Import auf doppelte Einträge.</p></div><p>Die Mikrorohre entstehen wie beim Anlegen in der Weboberfläche, siehe Abschnitt <a href="./21-projekte-und-stammdaten.html#_21-4-rohrtypen-und-mikrorohrfarben">Rohrtypen und Mikrorohrfarben</a>.</p><h2 id="_24-2-geopackage-schema-herunterladen" tabindex="-1">24.2 GeoPackage-Schema herunterladen <a class="header-anchor" href="#_24-2-geopackage-schema-herunterladen" aria-label="Permalink to &quot;24.2 GeoPackage-Schema herunterladen&quot;">​</a></h2><p>Das GeoPackage-Schema ist die Vorlage für Daten, die außerhalb von Qonnectra erfasst werden – in QGIS ohne Verbindung zur Datenbank, durch ein Ingenieurbüro, auf einem Tablet im Feld –, und die später übernommen werden sollen, siehe Abschnitt <a href="./26-netzdaten-in-qgis-bearbeiten.html#_26-4-feldaufnahme-uber-geopackage-und-ruckfuhrung">Feldaufnahme über GeoPackage und Rückführung</a>.</p><p>Welche Tabellen die Datei enthält, legen Sie in einer Konfiguration fest; was ein GeoPackage-Schema ist und wie Sie die Konfiguration anlegen, beschreibt Abschnitt <a href="./22-projektbezogene-konfiguration.html#_22-4-geopackage-schema-konfigurieren">GeoPackage-Schema konfigurieren</a>. Herunterladen:</p><ol><li>Öffnen Sie „GeoPackage-Schema-Konfigurationen“.</li><li>Haken Sie genau eine Konfiguration an.</li><li>Wählen Sie die Aktion „GeoPackage-Schema für ausgewählte Konfiguration herunterladen“ und klicken Sie auf „Ausführen“.</li></ol><p><img src="'+i+'" alt="Screenshot der GeoPackage-Schema-Konfigurationen mit Hervorhebung der angehakten Konfiguration, der gewählten Aktion darüber und der Schaltfläche „QGIS-Projekt konvertieren“ oben rechts" data-zoomable="true"></p><p>Die Datei enthält je ausgewählter Tabelle eine leere Tabelle mit allen Spalten der Datenbank, aber keine Daten. Die Stammdaten stehen in den Layern als Nummern; auch mitausgewählte Stammdatentabellen sind leer. Die Layer mit Geometrie liegen im Koordinatenbezugssystem der Installation, üblicherweise ETRS89 / UTM Zone 32N (EPSG:25832).</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Dieselbe Datei liefert die Schnittstelle unter <code>/api/v1/schema.gpkg</code> auf der Adresse der Schnittstelle, mit dem Parameter <code>layers</code> für die Auswahl, etwa <code>…/api/v1/schema.gpkg?layers=address,attributes_status_development</code>. Ohne Parameter enthält sie alle Tabellen. Abrufen darf sie jedes angemeldete Konto.</p></div><p>Neben der Download-Aktion steht oben rechts „QGIS-Projekt konvertieren“. Dort laden Sie ein QGIS-Projekt hoch, dessen Layer auf GeoPackage-Dateien verweisen, und erhalten es mit Verweisen auf die Datenbank von Qonnectra zurück. Das ist der Weg, ein Projekt, das mit dem leeren Schema aufgebaut wurde, auf den Bestand umzustellen; QGIS-Projekte für den QGIS-Server beschreibt Kapitel <a href="./27-qgis-server-und-kartendienste.html">QGIS-Server und Kartendienste</a>.</p><h2 id="_24-3-erst-und-massenbefullung-eines-projekts" tabindex="-1">24.3 Erst- und Massenbefüllung eines Projekts <a class="header-anchor" href="#_24-3-erst-und-massenbefullung-eines-projekts" aria-label="Permalink to &quot;24.3 Erst- und Massenbefüllung eines Projekts&quot;">​</a></h2><p>Ein neues Projekt füllen Sie in dieser Reihenfolge, weil jeder Schritt auf dem vorigen aufbaut:</p><ol><li><strong>Stammdaten prüfen und ergänzen</strong> – Status, Netzebenen, Firmen, Rohr- und Kabeltypen mit Farbzuordnungen, Netzknotentypen, siehe Kapitel <a href="./21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</li><li><strong>Projekt und Kennzeichen anlegen</strong>, siehe Abschnitt <a href="./21-projekte-und-stammdaten.html#_21-1-projekte-anlegen-und-vorbelegungen-setzen">Projekte anlegen und Vorbelegungen setzen</a>, samt Netzschema-, Rohrabzweig-Einstellungen und Kostensätzen, siehe Kapitel <a href="./22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>.</li><li><strong>Geometrien in QGIS übernehmen</strong> – Gebiete, Trassen, Netzknoten, Adressen, siehe Kapitel <a href="./26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>.</li><li><strong>Rohre importieren</strong>, siehe Abschnitt <a href="#_24-1-excel-import-der-rohre-vorlage-und-pflichtspalten">Excel-Import der Rohre: Vorlage und Pflichtspalten</a>.</li><li><strong>Rohre den Trassen zuordnen</strong> und die Mikrorohre verbinden, in der Weboberfläche, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/11-rohrzuordnung.html">Rohrzuordnung</a> und <a href="./../teil-a-anwenderhandbuch/12-rohrverzweigung.html">Rohrverzweigung</a>.</li><li><strong>Kabel, Netzknotenaufbau und Spleiße</strong> im Netzschema erfassen, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/14-netzschema.html">Netzschema</a>.</li></ol><p>Für Rohrzuordnung, Kabel und Spleiße gibt es keinen Massenimport; sie entstehen in der Weboberfläche.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Nach einer Übernahme an der Weboberfläche vorbei – aus QGIS oder direkt in die Datenbank – fehlt, was sonst beim Anlegen geschieht: Rohre bekommen keine Mikrorohre, Kabel keine Fasern. Ergänzen Sie sie mit den Aktionen des Administrationsbereichs, siehe Abschnitt <a href="./20-administrationsbereich.html#_20-2-suchen-filtern-und-massenbearbeitung">Suchen, Filtern und Massenbearbeitung</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Weboberfläche zeigt neue Daten nicht überall sofort. Kartenkacheln mit Inhalt hält der Server bis zu 30 Sekunden vor, leere Kacheln bis zu zehn Minuten; die Auswertungen im Dashboard bis zu fünf Minuten, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/04-dashboard.html">Dashboard</a>. Wurde ein Kartenausschnitt angesehen, solange er noch leer war, bleiben die übernommenen Objekte dort deshalb bis zu zehn Minuten unsichtbar – gerade bei der Erstbefüllung.</p></div>',21)])])}const g=n(o,[["render",l]]);export{b as __pageData,g as default};
